"""Generate docs/basemap1863/SOURCES-roads.md and features/roads-rail-water/README.md from the data files and the verification records (every number is read from a file)."""
import json, os, sys, collections, datetime
import numpy as np
sys.path.insert(0, os.path.dirname(__file__))
from geomlib import *
from sources import SRC
MD = os.path.join(OUT, '..', '..', 'SOURCES-roads.md')
RD = os.path.join(OUT, 'README.md')
def load(n):
    p = os.path.join(OUT, n + '.geojson')
    return json.load(open(p))['features'] if os.path.exists(p) else []
def jl(p):
    p = os.path.join(OUT, p); return json.load(open(p)) if os.path.exists(p) else {}
def tally(fs):
    c = collections.Counter(f['properties']['confidence'] for f in fs); return ', '.join(f'{k} {v}' for k, v in sorted(c.items()))
def km(fs):
    return round(sum(length_m(shape(f['geometry'])) for f in fs if f.get('geometry') and f['geometry']['type'] in ('LineString', 'MultiLineString')) / 1000, 1)
def main():
    roads, rails, water, br, wf, fences, lanes = [load(n) for n in ('roads', 'railways', 'waterways', 'bridges', 'water_features', 'fences', 'lanes')]
    rm = json.load(open(os.path.join(OUT, 'modern-roads-remove.json')))
    clsc = collections.Counter(r['cls'] for r in rm); clsk = collections.defaultdict(float)
    for r in rm: clsk[r['cls']] += r['length_m_in_box'] / 1000
    reg = jl('registration_sheet_a.json'); p5 = jl('verification/pass5_map_presence.json').get('results', {}); p6 = jl('verification/pass6_streams.json'); p7 = jl('verification/pass7_fences.json').get('results', {})
    p4b = jl('verification/pass4b_edge_presence.json').get('results', {}); p4c = jl('verification/pass4c_town.json'); pbr = jl('verification/pass_bridges.json').get('readings', {})
    v1, v2, v3, v4, v8 = [jl(f'verification/pass{i}.json') for i in (1, 2, 3, 4, 8)]
    rl = [v for v in p5.values() if v.get('samples', 0) >= 4]
    det = np.array([v['detection_rate'] for v in rl]); ctl = np.array([v['control_rate'] for v in rl])
    fc = collections.Counter(v['verdict'] for v in p7.values()); amb = sum(1 for v in p7.values() if v.get('ambiguous'))
    bc = collections.Counter(v['symbol'] for v in pbr.values())
    L = []; A = L.append
    A('# Roads, railroads, bridges, waterways, lanes and fences of July 1863: sources, methods, accuracy, licences')
    A('')
    A('Owner: `docs/basemap1863/features/roads-rail-water/` and this file. Generated by `scripts/gen_sources_md.py` on %s from the data files; every number below comes from a script in `scripts/` or a record in `verification/`, or is marked as read, not measured.' % datetime.date.today().isoformat())
    A('')
    A('## 0. What this is, and what it is not')
    A('')
    A('**This is a RECONSTRUCTION.** No aerial photograph of the battlefield from 1863 exists. Every feature here is inferred from documents and maps made later (the earliest large-scale survey of the ground is G. K. Warren\'s of 1868-69, five years after the battle; the Bachelder sheets used here are its 1876 reduction) and from the modern ground. It must be labelled as a reconstruction wherever it is shown.')
    A('')
    A('It does not claim to be an exact or complete copy of the 1863 landscape. What it claims is limited to what each feature record states: id, category, sources (title, sheet or page, URL, type), method, positional error in metres, confidence. Source types: **A1** primary map or record made 1863-69 by a survey or participant (the Warren/Bachelder sheet); **A2** later first-hand account or photograph; **B** secondary (NPS scholarship, compilations, modern open data). Confidence: **Documented** (a source names the feature and a map or document places it), **Estimated** (supported by class rules, modern geometry or a partial check; place inferred), **Contested**, **Unknown**. Where a feature is unknown the record says `Unknown`; nothing is drawn for it.')
    A('')
    A('**Measured accuracy, in one paragraph.** The period map used for the checks (Bachelder 1876 first-day sheet, LOC `cw0325000a`) was registered to the ground with the b-maps agent\'s Warren control points plus %d hand-read road lines; the leave-one-out error of that registration is **%s m (RMS) on the control points and %s m (RMS, median %s m) on the road lines**, and it is worse (not measured) where there are few constraints (far north-west, south-west, east of Rock Creek). Against that registration the catalogued roads show a drawn double line along %s percent of samples (median over %d roads with at least 4 samples; the same test displaced sideways finds one in %s percent). The positional error stated on each feature is 15-35 m for roads, 20-25 m for the railroad where the sheet was used and 30 m for streams.' % (
        reg.get('constraints', {}).get('hand_read_road_lines', 0), reg.get('leave_one_out_m', {}).get('gcp_rms'), reg.get('leave_one_out_m', {}).get('road_rms'), reg.get('leave_one_out_m', {}).get('road_median'),
        round(100 * float(np.median(det))), len(rl), round(100 * float(np.median(ctl)))))
    A('')
    A('## 1. Files (in `features/roads-rail-water/`)')
    A('')
    A('| File | What | Features | Confidence tally |')
    A('|---|---|---|---|')
    A(f'| `roads.geojson` (+ `.mercator.geojson`, EPSG:3857) | public roads and lanes of 1863 on their modern centreline, with period-map presence numbers | {len(roads)} ({km(roads)} km in the box) | {tally(roads)} |')
    A(f'| `lanes.geojson` | lane sections traced by hand from the period map | {len(lanes)} ({km(lanes)} km) | {tally(lanes)} |')
    A('| `lanes_inventory.json` | 21 lanes named by NPS for 1863, with route text, today\'s status and sources; geometry only where `lanes.geojson` has a trace | 21 | n/a |')
    A(f'| `railways.geojson` | Gettysburg Railroad, the unfinished grade, depot, Rock Creek trestle, post-1863 lines (`present_1863` false) | {len(rails)} | {tally(rails)} |')
    A(f'| `waterways.geojson` | NHD flowlines; named streams Estimated, unnamed channels Unknown | {len(water)} ({km(water)} km) | {tally(water)} |')
    A(f'| `bridges.geojson` | crossings of 1863 roads with named streams | {len(br)} | {tally(br)} |')
    A(f'| `water_features.geojson` | Spangler\'s Spring, mill dams, Plum Run marsh (ponds named by NPS but unlocated are in `water_features_no_geometry.json`) | {len(wf)} | {tally(wf)} |')
    A(f'| `fences.geojson` | OSM-mapped fences and walls checked against the sheet; `draw: true` only where a drawn line was found | {len(fences)} ({sum(1 for f in fences if f["properties"].get("draw"))} with draw true) | {tally(fences)} |')
    A('| `modern-roads-remove.json` / `.csv` | every TIGER/Line road edge in the box classified (section 4) | %d | |' % len(rm))
    A('| `registration_sheet_a.json` | the registration of the period map to the ground, with leave-one-out numbers | | |')
    A('| `verification/` | the eight verification passes (section 7) | | |')
    A('| `evidence/` | eight small JPEG figures: overlays on the period map (LOC, public domain) | | |')
    A('| `scripts/` | every script that produced the files; caches (PDFs, TIGER, NHD, OSM, map renders) are in `tmp/b1863/roads/`, not committed | | |')
    A('')
    A('Box: the Battle Studio data box (`docs/pitch/anim2/basemap/plan.json`: west -77.3178, south 39.77, east -77.18, north 39.8594) plus the plan\'s 1,200 m margin (west %.4f, south %.4f, east %.4f, north %.4f). The period map covers about lng -77.289 to -77.193 and lat 39.779 to 39.862; outside it nothing was checked against a map.' % (XW, XS, XE, XN))
    A('')
    A('## 2. Licence and attribution table')
    A('')
    A('| Source | Used for | Licence | Attribution |')
    A('|---|---|---|---|')
    A('| U.S. Census Bureau, TIGER/Line 2023 Roads, Adams County PA | modern centrelines; the removal table | public domain | "Source: U.S. Census Bureau, TIGER/Line Shapefiles" |')
    A('| USGS National Hydrography Dataset (high resolution), The National Map | stream flowlines | public domain | "Data: USGS National Hydrography Dataset" |')
    A('| National Park Service documents (npshistory.com mirror and irma.nps.gov): Cultural Landscapes Inventories (Gettysburg Landscape; First Day; Emmitsburg Road Ridge; Pickett\'s Charge; Little Round Top), Cultural Landscape Reports (1st Corps 2021; Record of Treatment 2018; Little Round Top 2012), Treatment Philosophy: The 1863 Landscape (2004), Historical Base Map documentation (1958) | what existed, with PDF page references checked against the text | works of the U.S. Government: public domain | "National Park Service, Gettysburg NMP" |')
    A('| Library of Congress, Geography and Map Division: Map of the battle field of Gettysburg (Bachelder 1876, from Warren 1868-69), item 99447491, sheet cw0325000a; Early collection scan cw0353500 (via the b-maps agent); Elliott 1864 (cw0333000) and the 1863 map cw0355000 were looked at, not used for measurements | period road, lane, fence, stream, bridge and railroad drawing: read for the checks | public domain; the figures in `evidence/` are crops of it | "Library of Congress, Geography and Map Division" |')
    A('| OpenStreetMap contributors (Overpass extract, 19 Oct 2026) | rail lines, abandoned Round Top Branch, mapped fences and walls (candidates), building names | ODbL 1.0: attribution and share-alike apply to the derived database | "(c) OpenStreetMap contributors"; the rail and fence files say so in `method` |')
    A('| Wikipedia (CC BY-SA 4.0): Wheatfield Road; Gettysburg station. AARoads wiki: US 15 in Pennsylvania | facts only: road description, depot and trestle facts, bypass opening date (28 June 1963) | facts cited, no text copied | cited in the records |')
    A('')
    A('Not used, on purpose: Google Earth, Google Maps, Bing, Maxar, Mapbox imagery (their terms forbid it). The Overpass server answered 502 for part of the session and was retried 60-120 s apart; the LOC image service answered 503 once and was left alone for several minutes. No source was reached through a block.')
    A('')
    A('## 3. How each class was built')
    A('')
    A('1. **Public roads and neighbourhood lanes on a modern line (29 records)** - the road is catalogued from NPS statements (the ten-road list, county-road list, individual road histories) and its geometry is the TIGER/Line 2023 edge(s) of that route, because the pikes and county roads were re-surfaced in place. For each road the period map was then tested (`scripts/map_check.py`): a drawn double line along the road within +-16 px (32 m) of the registered position. Confidence is Documented when an NPS text names the road and the sheet shows it; Estimated when only the sheet (RD-025 to RD-029, five roads that no NPS text read here names) or only class rules support it. The sheet is dated 1868-69, so a road "drawn on the sheet" is not proof for July 1863; where NPS text does not date a road the record says so.')
    A('2. **Lanes** - 21 lanes named by NPS are inventoried with sources; 4 sections are traced from the sheet (Trostle-Weikert-Swisher west and east, Codori east, H. Spangler lane). The Spangler lane trace lies within 7 m (median) of the existing NPS lane, an independent check; the others are 27-36 m from the nearest modern horse-trail line or have none (the lane is lost). The remaining 18 of the 21 lanes have no geometry (stated, not guessed).')
    s1 = next((f['properties'].get('snap_stats', {}) for f in rails if f['id'] == 'RL-001'), {}); s2 = next((f['properties'].get('snap_stats', {}) for f in rails if f['id'] == 'RL-002'), {})
    A('3. **Railroads** - the Gettysburg (Hanover Junction, Hanover and Gettysburg) Railroad reached the borough from the east in 1858; the grade west of the borough with its three cuts was graded but not laid. The modern CSX line is on the same corridor; its geometry was **laterally snapped, every 40 m, to the double line drawn on the sheet** (`scripts/snap.py`): median shift %s m (east line, 90th percentile %s m, maximum %s m) and %s m (west grade, 90th percentile %s m, maximum %s m); the snapped lines lie on the drawn lines in the overlay figures `evidence/rail-grade-overlay-*.jpg`. Where the sheet shows no clear line within 34 px or lies off the sheet the modern line is kept. The grade west of the sheet edge is flagged Unknown (RL-002W). The depot (1858) and the Rock Creek trestle (burned 27 June 1863) are points. Round Top Branch, the electric railway, later spurs and the Reading depot (1884) are post-1863 and flagged `present_1863: false`.' % (s1.get('median_shift_m'), s1.get('p90_shift_m'), s1.get('max_shift_m'), s2.get('median_shift_m'), s2.get('p90_shift_m'), s2.get('max_shift_m')))
    A('4. **Streams** - NHD high-resolution flowlines (modern courses). Compared with the drawn creek at 14 stations: median offset %s m, maximum %s m (`verification/pass6_streams.json`); error stated 30 m. Unnamed channels are Unknown (could be modern ditches). Modern ponds (154 NHD waterbodies in the box) are not 1863 features: NPS names two ponds on the 1863 battlefield, McPherson\'s (still there) and Biesecker\'s (removed), and neither is located by a source read.' % (p6.get('summary', {}).get('median_abs_m'), p6.get('summary', {}).get('max_abs_m')))
    A('5. **Bridges and fords** - at TIGER x NHD crossings, type by class rule (bridges on the turnpikes and county roads, fords elsewhere: NPS-TREAT-2004 p79). High-resolution crops of the sheet were read at each crossing: %s (`verification/pass_bridges.json`). A "seen" symbol upgrades the record to Documented; the position stays the modern crossing (error 30 m).' % ', '.join(f'{k} {v}' for k, v in sorted(bc.items())))
    A('6. **Fences and walls** - the NPS rebuilds fences on documented 1863 lines (`NPS-TREAT-2004` p69) and OSM mappers traced them, so a mapped fence is a candidate, not evidence (some park fences stand in non-historic places, CLI First Day p58, p61-62). Each of the %d candidates of at least 40 m on the sheet was tested for a continuous drawn line along it: %s, of which %d ambiguous (a parallel line within 8 px). The same test on the candidates shifted 300 m sideways confirms 2-4 percent (5-11 of 307), so about 83 percent of the confirmations are expected to be right. Only confirmed, non-ambiguous candidates have `draw: true` (%d); the fence style of 1863 is not read from the sheet. A separate list of the NPS fence installations (names, GIS ids, 1863 documentation they cite) is in the CLR Record of Treatment vol. I (pdf p176-235, p271-302) and was read but not converted to geometry: its boundaries are given by field names, not coordinates.' % (sum(1 for v in p7.values() if v['verdict'] in ('confirmed', 'not confirmed')), dict(fc), amb, sum(1 for f in fences if f['properties'].get('draw'))))
    A('')
    A('## 4. Modern roads that did not exist in 1863 (summary; the full table with TIGER ids and the period-map result per edge is `modern-roads-remove.csv`)')
    A('')
    A('| Class | TIGER edges | km in box | Basis |')
    A('|---|---|---|---|')
    names = {'ROAD_1863_SAME_LINE': 'catalogued 1863 road on its modern line', 'DUPLICATE_ROUTE_DESIGNATION': 'repeat of an 1863 road under a route number (>60 percent of its length within 8 m of a catalogued road)',
             'EXPRESSWAY_US15': 'US 15 Gettysburg bypass, opened 28 June 1963 (AARoads)', 'RAMP_OR_TURN_LANE': 'interchange ramp / turn lane (TIGER S1630, S1640)', 'NPS_MEMORIAL_AVENUE': 'NPS memorial avenue, 1882-1920 (CLI Little Round Top p64-67; CLI Emmitsburg Road Ridge p89-92; CLI Pickett\'s Charge p88-90; CLI First Day p62)',
             'PRIVATE_DRIVE': 'private road or driveway (TIGER S1740)', 'PARKING_LOT_ROAD': 'parking-lot road (S1780)', 'WALKING_PATH': 'walking path (S1710)', 'ALLEY': 'alley, undecided', 'TOWN_STREET_UNDECIDED': 'street inside the borough footprint, undecided (the town check was rejected, section 7 pass 4c)',
             'RURAL_ROAD_UNDECIDED': 'long rural road, no 1863 source read and not drawn on the sheet or off the sheet: undecided', 'POST_1863_STREET_OR_DRIVE': 'short street, court, drive or lane of the modern pattern (suburban subdivisions since the 1950s, CLI First Day p23); no source places a road there and none is drawn on the sheet where the sheet covers it',
             'DRAWN_ON_1876_SHEET': 'a road is drawn along this line on the sheet (1868-69): candidate 1863 road, NOT removed until decided'}
    for k, v in sorted(clsc.items(), key=lambda x: -clsk[x[0]]):
        A(f'| {k} | {v} | {clsk[k]:.1f} | {names.get(k, k)} |')
    A('')
    A('Modern changes to roads that did exist (read in the NPS texts): Emmitsburg Road widened and its fences set back 10 feet or more by the 1930s (CLI Emmitsburg Road Ridge p90); United States Avenue (the western half of the Trostle-Weikert lane) built 1895 and realigned 1935-43 (p90-91); Sickles Avenue 1887/1895-97; Hancock Avenue 1882; Wheatfield Road altered 1839 and 1934-39 (CLI Little Round Top p67); Sykes Avenue realigned 1935-36 (p67); the Gettysburg Electric Railway on the west side of Emmitsburg Road 1893-1916 and the Round Top Railroad 1884-1942 (p89-90).')
    A('')
    A('## 5. Registration of the period map (what every check rests on)')
    A('')
    A('`registration_sheet_a.json`: the b-maps agent\'s affine for the sheet (`docs/basemap1863/maps/transforms/bachelder-1876-sheet1.json`) plus a smooth displacement field (grid 450 px, lambda 3) fitted to %s Warren control points mapped onto the sheet by SIFT and %s hand-read road lines. Fit residual: %s m RMS (control points), %s m (road lines). Leave-one-out: control points %s m RMS (median %s, max %s), road lines %s m RMS (median %s, max %s). Caveats stored in the file: constraints are dense along the main roads and sparse in the north-west, south-west and east; the hand-read road lines assume the modern centreline is on the 1863 road line; the numbers are leave-one-out values, not an independent ground survey.' % (
        reg.get('constraints', {}).get('warren_gcps_mapped_to_sheet_a'), reg.get('constraints', {}).get('hand_read_road_lines'), reg.get('fit_residual_m', {}).get('gcp_rms'), reg.get('fit_residual_m', {}).get('road_rms'),
        reg.get('leave_one_out_m', {}).get('gcp_rms'), reg.get('leave_one_out_m', {}).get('gcp_median'), reg.get('leave_one_out_m', {}).get('gcp_max'), reg.get('leave_one_out_m', {}).get('road_rms'), reg.get('leave_one_out_m', {}).get('road_median'), reg.get('leave_one_out_m', {}).get('road_max')))
    A('')
    A('## 6. What is uncertain or not done (Unknown, kept visible)')
    A('')
    A('- **Dating**: the sheet is 1868-69; NPS says roads and lanes persisted, but a road shown there is not individually dated to July 1863. Records say so.')
    A('- **Borough streets**: the borough grid is mostly older than 1863 but each street is not established (pass 4c rejected). 60 edges stay undecided. The Harrisburg, Mummasburg and Carlisle roads end at the borough edge in the data; their 1863 routing to the Diamond is not established.')
    A('- **Roads off the sheet** (far west, south, east): geometry is the modern line with no map check; Low Dutch Road and the east part of Hanover Road, the west ends of the Chambersburg Pike and Black Horse Tavern Road have `positional_error_m` 25 with no measurement behind it. The grade west of the sheet is Unknown.')
    A('- **Lanes**: 18 of 21 named lanes have no geometry. Fence styles of 1863 are not read from the sheet. %d of %d mapped fences are not drawn. The two 1863 ponds are unlocated.' % (sum(1 for f in fences if not f['properties'].get('draw')), len(fences)) + '')
    A('- **Bridges**: only crossings of 1863 roads with named streams; %d of %d have a bridge symbol seen or probable on the sheet, the rest are class-rule estimates; stream crossings in the borough (Stevens Run) are Unknown.' % (sum(1 for f in br if f['properties'].get('period_map_symbol') in ('seen', 'probable')), len(br)) + '')
    A('- **Streams**: courses are modern; NPS says they have changed; mill-dam ponds and the Rose Run drain (placed underground 1980s) are not drawn.')
    A('- **Orchards, woods, wetlands, earthworks, springs other than Spangler\'s**: not in this layer.')
    A('')
    A('## 7. The eight verification passes (details in `verification/`)')
    A('')
    A('| Pass | What | Result |')
    A('|---|---|---|')
    A(f'| 1 schema | every record has id, category, subtype, sources with title/page/URL/type/quote, method, positional error, confidence | errors {len(v1.get("errors", []))}, warnings {len(v1.get("warnings", []))}; counts {v1.get("counts")} |')
    A(f'| 2 citations | the content words of each NPS paraphrase looked up on the cited PDF page of the extracted text | {v2.get("checked")} citations checked, {v2.get("ok")} with at least 45 percent of content words on the page, {len(v2.get("weak", []))} weak, {len(v2.get("nopage", []))} without text; LOC, OSM, NHD and Wikipedia citations are not text-checked |')
    A(f'| 3 geometry | valid, inside the box, ids unique; road ends not joined within 3 m | errors {len(v3.get("errors", []))}; {len(v3.get("gaps", []))} road ends not joined (listed; these are borough-edge and box-edge ends) |')
    A(f'| 4 removal table | all TIGER edges in the box classified; 1863 roads never listed for removal; every edge tested against the sheet (4b); borough street check (4c) | {v4.get("classified")} of {v4.get("edges_in_box")} classified; inconsistent {len(v4.get("inconsistent", []))}; 4b: {sum(1 for v in p4b.values() if v.get("drawn"))} edges drawn on the sheet of {sum(1 for v in p4b.values() if v.get("on_sheet"))} on the sheet; 4c rejected (known streets fail) |')
    A(f'| 5 roads on the map | drawn double line along each catalogued road vs a displaced control | median detection {round(100 * float(np.median(det)))} percent, control {round(100 * float(np.median(ctl)))} percent over {len(rl)} roads (`pass5_map_presence.json`); also 26 hand-read stations (`roadreads_a.json`) |')
    A(f'| 6 streams | 14 stations read by eye | median offset {p6.get("summary", {}).get("median_abs_m")} m, max {p6.get("summary", {}).get("max_abs_m")} m |')
    A(f'| 7 rail, bridges, fences, lanes | grade overlay and snap statistics; bridge symbol readings; fence continuity test with false-positive control; lane cross-check | see sections 3 and the records; fences {dict(fc)}, ambiguous {amb} |')
    A(f'| 8 honesty | no claim of an exact or complete copy, no "1:1", no "100 percent"; the RECONSTRUCTION label; Unknown carries no geometry flag | hits {len(v8.get("hits", []))}; label present {v8.get("reconstruction_label")} |')
    A('')
    A('These eight passes check this layer (roads, rail, water, lanes, fences). The eight-fold check the owner asked for on the whole map is the integrator\'s: it must also use these records.')
    A('')
    A('## 8. Reproduce')
    A('')
    A('`python scripts/tiger_dump.py` (TIGER zip cached in `tmp/b1863/roads/cache`), `build_roads.py`, `build_water.py`, `build_rail_fence.py`, `build_bridges.py`, `build_misc.py`, `build_lanes.py`, `build_removal.py`, `map_check.py`, `edge_presence.py`, `fence_check.py`, `verify.py`, `gen_sources_md.py`. The registration needs the LOC renders of cw0325000a and cw0353500 (50 percent) and the b-maps transforms; `scanmatch.py`, `roadgcp.py`, `fieldfit.py`, `regtf.py`.')
    open(MD, 'w', encoding='utf8').write('\n'.join(L))
    print('wrote', MD, len(L), 'lines')
if __name__ == '__main__':
    main()
